import { Agent, Workflow, Guardrail, GuardrailType } from '@voltagent/core';
import { openai } from '@ai-sdk/openai';
import { generateText } from '@ai-sdk/openai';

// Define PII patterns for regex-based detection
const EMAIL_PATTERN = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g;
const PHONE_PATTERN = /\b(?:\+?1[-.\s]?)?\(?[0-9]{3}\)?[-.\s]?[0-9]{3}[-.\s]?[0-9]{4}\b/g;
const SSN_PATTERN = /\b\d{3}[-.\s]?\d{2}[-.\s]?\d{4}\b/g;
const CREDIT_CARD_PATTERN = /\b(?:\d[ -]*?){13,16}\b/g;

/**
 * VoltAgent workflow for PII redaction from transcribed voice text
 */
export const piiRedactionWorkflow = new Workflow({
  name: 'pii-redaction-workflow',
  description: 'Detects and redacts PII from transcribed voice text',

  // Define the agent with guardrails
  agent: new Agent({
    name: 'pii-redaction-agent',
    description: 'Agent that detects and redacts Personally Identifiable Information',
    provider: openai('gpt-4o-mini'),

    // Define guardrails for PII detection
    guardrails: [
      new Guardrail({
        name: 'email-guardrail',
        type: GuardrailType.REDACTION,
        pattern: EMAIL_PATTERN,
        replacement: '[REDACTED_EMAIL]',
        description: 'Redacts email addresses'
      }),

      new Guardrail({
        name: 'phone-guardrail',
        type: GuardrailType.REDACTION,
        pattern: PHONE_PATTERN,
        replacement: '[REDACTED_PHONE]',
        description: 'Redacts phone numbers'
      }),

      new Guardrail({
        name: 'ssn-guardrail',
        type: GuardrailType.REDACTION,
        pattern: SSN_PATTERN,
        replacement: '[REDACTED_SSN]',
        description: 'Redacts Social Security Numbers'
      }),

      new Guardrail({
        name: 'credit-card-guardrail',
        type: GuardrailType.REDACTION,
        pattern: CREDIT_CARD_PATTERN,
        replacement: '[REDACTED_CREDIT_CARD]',
        description: 'Redacts credit card numbers'
      })
    ]
  })
});

/**
 * Main function to redact PII from input text
 * Uses VoltAgent workflow with regex-based detection and AI-based name detection
 * 
 * @param input - The input text (simulating transcribed audio)
 * @returns Promise<string> - The redacted text with PII replaced by [REDACTED]
 */
export async function redactPii(input: string): Promise<string> {
  try {
    // Step 1: Apply regex-based guardrails for structured PII
    let redactedText = input;

    // Redact emails
    redactedText = redactedText.replace(EMAIL_PATTERN, '[REDACTED_EMAIL]');

    // Redact phone numbers
    redactedText = redactedText.replace(PHONE_PATTERN, '[REDACTED_PHONE]');

    // Redact SSNs
    redactedText = redactedText.replace(SSN_PATTERN, '[REDACTED_SSN]');

    // Redact credit card numbers
    redactedText = redactedText.replace(CREDIT_CARD_PATTERN, '[REDACTED_CREDIT_CARD]');

    // Step 2: Use AI to detect and redact names and other PII
    // This is necessary because names are hard to detect with regex alone
    if (redactedText === input) {
      // If no structured PII was found, still run AI detection for names
      const { text: aiRedacted } = await generateText({
        model: openai('gpt-4o-mini'),
        prompt: `You are a PII detection and redaction system. Your task is to identify and redact Personally Identifiable Information from the given text.

Rules:
- Identify names (first names, last names, full names) and replace them with [REDACTED_NAME]
- Identify addresses and replace them with [REDACTED_ADDRESS]
- Identify dates of birth and replace them with [REDACTED_DOB]
- Identify any other sensitive personal information and replace it with [REDACTED]
- Keep all other text exactly as is
- Return ONLY the redacted text, no explanations

Text to redact: ${input}`,
        temperature: 0.0, // Use low temperature for consistent results
      });

      redactedText = aiRedacted;
    } else {
      // If structured PII was found, run AI detection on the already redacted text
      const { text: aiRedacted } = await generateText({
        model: openai('gpt-4o-mini'),
        prompt: `You are a PII detection and redaction system. Your task is to identify and redact any remaining Personally Identifiable Information from the given text.

Rules:
- Identify names (first names, last names, full names) and replace them with [REDACTED_NAME]
- Identify addresses and replace them with [REDACTED_ADDRESS]
- Identify dates of birth and replace them with [REDACTED_DOB]
- Identify any other sensitive personal information and replace it with [REDACTED]
- Keep all other text exactly as is
- Return ONLY the redacted text, no explanations

Text to redact: ${redactedText}`,
        temperature: 0.0,
      });

      redactedText = aiRedacted;
    }

    // Step 3: Normalize all redaction markers to [REDACTED] as per requirements
    redactedText = redactedText
      .replace(/\[REDACTED_EMAIL\]/g, '[REDACTED]')
      .replace(/\[REDACTED_PHONE\]/g, '[REDACTED]')
      .replace(/\[REDACTED_SSN\]/g, '[REDACTED]')
      .replace(/\[REDACTED_CREDIT_CARD\]/g, '[REDACTED]')
      .replace(/\[REDACTED_NAME\]/g, '[REDACTED]')
      .replace(/\[REDACTED_ADDRESS\]/g, '[REDACTED]')
      .replace(/\[REDACTED_DOB\]/g, '[REDACTED]');

    return redactedText;
  } catch (error) {
    console.error('Error in PII redaction:', error);
    throw new Error('Failed to redact PII from input text');
  }
}

/**
 * Alternative implementation using the VoltAgent workflow directly
 * This demonstrates how to use the workflow programmatically
 */
export async function redactPiiWithWorkflow(input: string): Promise<string> {
  try {
    // Execute the workflow with the input text
    const result = await piiRedactionWorkflow.execute({
      input: input,
      options: {
        enableGuardrails: true
      }
    });

    return result.output;
  } catch (error) {
    console.error('Error in VoltAgent workflow execution:', error);
    throw new Error('Failed to execute PII redaction workflow');
  }
}

// Export the workflow for external use
export { piiRedactionWorkflow };

// Default export for compatibility
export default {
  redactPii,
  redactPiiWithWorkflow,
  piiRedactionWorkflow
};

