import { Agent, createWorkflow, createInputGuardrail, createDefaultPIIGuardrails, VoltAgent } from '@voltagent/core';
import { openai } from '@ai-sdk/openai';
import { generateText } from 'ai';

/**
 * PII Redaction Agent
 * A VoltAgent that detects and redacts Personally Identifiable Information from transcribed voice text
 */
export const piiRedactionAgent = new Agent({
  name: 'pii-redaction-agent',
  instructions: 'You are a PII detection and redaction system. Your task is to identify and redact Personally Identifiable Information from the given text.',
  model: openai('gpt-4o-mini'),
});

/**
 * VoltAgent workflow for PII redaction from transcribed voice text
 * Uses guardrails to detect and redact PII before processing
 */
export const piiRedactionWorkflow = createWorkflow({
  id: 'pii-redaction-workflow',
  name: 'PII Redaction Workflow',
  description: 'Detects and redacts PII from transcribed voice text',

  // Define input schema
  input: {
    type: 'object',
    properties: {
      text: {
        type: 'string',
        description: 'The input text to redact PII from'
      }
    },
    required: ['text']
  },

  // Define output schema
  output: {
    type: 'object',
    properties: {
      redactedText: {
        type: 'string',
        description: 'The redacted text with PII replaced'
      },
      detectedPII: {
        type: 'array',
        items: {
          type: 'string'
        },
        description: 'List of PII types detected'
      }
    }
  },

  // Add input guardrails for PII detection
  inputGuardrails: createDefaultPIIGuardrails(),

  // Execute the workflow
  execute: async ({ input }) => {
    const { text } = input;

    // Step 1: Apply regex-based detection for structured PII
    let redactedText = text;
    const detectedPII: string[] = [];

