export const piiRedactionAgent = new Agent({
  name: 'pii-redaction-agent',
  instructions: 'You are a PII detection and redaction system. Your task is to identify and redact Personally Identifiable Information from the given text.',
  model: openai('gpt-4o-mini'),
  inputGuardrails: createDefaultPIIGuardrails()
});

/**
 * Custom PII input guardrail for additional PII detection
 */
export const customPIIGuardrail = createInputGuardrail({
  id: 'custom-pii-guardrail',
  name: 'Custom PII Guardrail',
  description: 'Detects and redacts additional PII patterns',
  validate: async ({ input }) => {
    const text = typeof input === 'string' ? input : JSON.stringify(input);

    // Check for email addresses
    const emailPattern = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g;
    const hasEmail = emailPattern.test(text);

    // Check for phone numbers
    const phonePattern = /\b(?:\+?1[-.\s]?)?\(?[0-9]{3}\)?[-.\s]?[0-9]{3}[-.\s]?[0-9]{4}\b/g;
    const hasPhone = phonePattern.test(text);

    // Check for SSNs
    const ssnPattern = /\b\d{3}[-.\s]?\d{2}[-.\s]?\d{4}\b/g;
    const hasSSN = ssnPattern.test(text);

    // Check for credit card numbers
    const creditCardPattern = /\b(?:\d[ -]*?){13,16}\b/g;
    const hasCreditCard = creditCardPattern.test(text);

    const detectedPII: string[] = [];
    if (hasEmail) detectedPII.push('email');
    if (hasPhone) detectedPII.push('phone');
    if (hasSSN) detectedPII.push('ssn');
    if (hasCreditCard) detectedPII.push('credit_card');

    if (detectedPII.length > 0) {
      return {
        isValid: false,
        errorMessage: `PII detected: ${detectedPII.join(', ')}`,
        action: 'reject'
      };
    }

    return { isValid: true };
  }
});

